#include <cstdio>
#include <typeinfo>

struct A { virtual ~A() = default; };
struct C : A {};

int main() {
  A a;
  try {
    C& c = dynamic_cast<C&>(a);
    (void)c;
    std::puts("ok");
  } catch (const std::bad_cast&) {
    std::puts("bad_cast");
  }
}

struct Base { virtual ~Base() = default; };
struct Derived : Base { int extra = 0; };

int main() {
  Base b;
  Derived* d = static_cast<Derived*>(&b);
  (void)d;  // d is never dereferenced
}

struct Base { int x = 1; };
struct Other { int y = 2; };
struct Derived : Other, private Base {};

int main() {
  Derived d;
  Base* b = (Base*)&d;
  return b->x;
}

#include <cstdio>

struct A { virtual ~A() = default; int a = 0; };
struct B { virtual ~B() = default; int b = 0; };
struct C : A, B {};

int main() {
  C c;
  B* pb = &c;
  std::printf("%d\n", dynamic_cast<void*>(pb) == static_cast<void*>(&c));
}
